use super::*;
fn note(id:&str,body:&str)->NewEntry{NewEntry{workspace_id:id.into(),kind:"note".into(),title:"Research note".into(),body:body.into(),..Default::default()}}
fn publish(s:&Store,mut input:NewEntry)->RefractResult<WorkspaceView>{let p=s.margin_preview(&input)?;input.review_hash=Store::margin_preview_hash(&p)?;s.margin_publish(&input)}
fn transfer(a:&Store,b:&Store,id:&str,kind:&str)->ExchangeResult{let owner=a.margin_view(id).unwrap().owner;let packet=a.margin_export_packet(&ExportRequest{workspace_id:id.into(),recipient:b.margin_contact().unwrap().data.signing_key,kind:kind.into()}).unwrap();b.margin_import_packet(&ImportRequest{packet,expected_owner:owner}).unwrap()}
fn pair(role:&str)->(Store,Store,String){let a=Store::open_in_memory().unwrap();let b=Store::open_in_memory().unwrap();let ws=a.margin_create("Research").unwrap();a.margin_member(&ws.id,&b.margin_contact().unwrap(),role).unwrap();a.margin_enable(&ws.id,true).unwrap();transfer(&a,&b,&ws.id,"invite");b.margin_enable(&ws.id,true).unwrap();(a,b,ws.id)}
#[test]fn private_default_and_selected_recipient_encryption(){let a=Store::open_in_memory().unwrap();let b=Store::open_in_memory().unwrap();let c=Store::open_in_memory().unwrap();let ws=a.margin_create("Research").unwrap();publish(&a,note(&ws.id,"Selected note only")).unwrap();assert!(!ws.exchange_enabled);a.margin_member(&ws.id,&b.margin_contact().unwrap(),"editor").unwrap();let q=ExportRequest{workspace_id:ws.id.clone(),recipient:b.margin_contact().unwrap().data.signing_key,kind:"invite".into()};assert!(a.margin_export_packet(&q).is_err());a.margin_enable(&ws.id,true).unwrap();let packet=a.margin_export_packet(&q).unwrap();assert!(!packet.contains("Selected note only"));assert!(c.margin_inspect(&packet).is_err());assert!(b.margin_import_packet(&ImportRequest{packet:packet.clone(),expected_owner:"wrong".into()}).is_err());assert!(b.margin_list().unwrap().is_empty());let owner=ws.owner;let result=b.margin_import_packet(&ImportRequest{packet,expected_owner:owner}).unwrap();let joined=b.margin_view(&result.workspace_id).unwrap();assert!(!joined.exchange_enabled);assert_eq!(joined.entries[0].versions[0].body,"Selected note only");assert!(b.list_items(100,0).unwrap().is_empty());}
#[test]fn concurrent_versions_converge_without_lww_data_loss(){let(a,b,id)=pair("editor");let ws=publish(&a,note(&id,"base")).unwrap();transfer(&a,&b,&id,"sync");let r=ws.entries[0].versions[0].clone();for(s,text)in[(&a,"owner offline"),(&b,"editor offline")]{s.margin_edit(&EditEntry{workspace_id:id.clone(),entry_id:r.entry_id.clone(),chosen_revision:r.id.clone(),expected_heads:vec![r.id.clone()],title:r.title.clone(),body:text.into(),done:false,deleted:false}).unwrap();}let a_packet=a.margin_export_packet(&ExportRequest{workspace_id:id.clone(),recipient:b.margin_contact().unwrap().data.signing_key,kind:"sync".into()}).unwrap();let b_packet=b.margin_export_packet(&ExportRequest{workspace_id:id.clone(),recipient:a.margin_contact().unwrap().data.signing_key,kind:"sync".into()}).unwrap();let owner=a.margin_view(&id).unwrap().owner;for(s,packet)in[(&a,b_packet),(&b,a_packet)]{s.margin_import_packet(&ImportRequest{packet,expected_owner:owner.clone()}).unwrap();}let av=a.margin_view(&id).unwrap();let bv=b.margin_view(&id).unwrap();assert!(av.entries[0].conflict);assert_eq!(av.entries[0].versions,bv.entries[0].versions);let chosen=&av.entries[0].versions[0];a.margin_edit(&EditEntry{workspace_id:id.clone(),entry_id:chosen.entry_id.clone(),chosen_revision:chosen.id.clone(),expected_heads:av.entries[0].versions.iter().map(|v|v.id.clone()).collect(),title:chosen.title.clone(),body:"explicitly resolved".into(),done:false,deleted:false}).unwrap();transfer(&a,&b,&id,"sync");let result=b.margin_view(&id).unwrap();assert!(!result.entries[0].conflict);assert_eq!(result.entries[0].history_count,4);assert_eq!(result.entries[0].versions[0].body,"explicitly resolved");}
#[test]fn viewer_cannot_write_publish_invite_or_forge_editor_packet(){let(a,b,id)=pair("viewer");assert!(publish(&b,note(&id,"forbidden")).is_err());let q=ExportRequest{workspace_id:id.clone(),recipient:a.margin_contact().unwrap().data.signing_key,kind:"sync".into()};assert!(b.margin_export_packet(&q).is_err());let(p,_,_,_)=b.margin_load(&id).unwrap();let payload=serde_json::json!({"policy":p,"records":[],"acknowledged_hash":null});let me=b.margin_identity_private().unwrap();let packet=secure::seal(&me,&a.margin_contact().unwrap(),&id,p.data.epoch,"sync",&json(&payload).unwrap()).unwrap();assert!(a.margin_import_packet(&ImportRequest{packet,expected_owner:p.data.owner}).is_err());}
#[test]fn policy_revocation_is_enforced_when_learned_and_old_packets_stay_rejected(){let(a,b,id)=pair("editor");publish(&b,note(&id,"old epoch pending")).unwrap();let old=b.margin_export_packet(&ExportRequest{workspace_id:id.clone(),recipient:a.margin_contact().unwrap().data.signing_key,kind:"sync".into()}).unwrap();let owner=a.margin_view(&id).unwrap().owner;a.margin_member(&id,&b.margin_contact().unwrap(),"removed").unwrap();assert!(a.margin_import_packet(&ImportRequest{packet:old,expected_owner:owner}).is_err());transfer(&a,&b,&id,"policy");assert_eq!(b.margin_view(&id).unwrap().role,"removed");assert!(publish(&b,note(&id,"forbidden")).is_err());assert_eq!(b.margin_view(&id).unwrap().entries[0].versions[0].body,"old epoch pending");}
#[test]fn receipts_are_explicit_bound_to_recipient_and_replays_are_idempotent(){let(a,b,id)=pair("viewer");publish(&a,note(&id,"read me")).unwrap();let result=transfer(&a,&b,&id,"sync");assert!(a.margin_view(&id).unwrap().pending_transfers>=1);let receipt=b.margin_receipt(&id,&result.packet_hash).unwrap();let owner=a.margin_view(&id).unwrap().owner;let first=a.margin_import_packet(&ImportRequest{packet:receipt.clone(),expected_owner:owner.clone()}).unwrap();assert!(!first.duplicate);assert!(a.margin_import_packet(&ImportRequest{packet:receipt,expected_owner:owner}).unwrap().duplicate);let rows=a.margin_transfers(&id).unwrap();assert!(rows.as_array().unwrap().iter().any(|r|r["hash"]==result.packet_hash&&r["acknowledged_ts"].is_i64()));b.margin_enable(&id,false).unwrap();assert!(b.margin_receipt(&id,&result.packet_hash).is_err());}
#[test]fn resilient_anchors_do_not_guess_changed_quotes_or_positions(){use refract_core::{Block,BlockKind};let blocks=vec![Block{idx:0,kind:BlockKind::Heading1,text:"First".into()},Block{idx:1,kind:BlockKind::Paragraph,text:"Before selected quote after.".into()}];let mut a=annotation_engine::build_anchor(&blocks,1,"selected quote").unwrap();a.document_id="doc-a".into();assert_eq!(annotation_engine::resolve_document_anchor(&a,"doc-b",&blocks).0,annotation_engine::AnchorStatus::Lost);let changed=vec![Block{idx:0,kind:BlockKind::Paragraph,text:"Before entirely different after.".into()}];assert_eq!(annotation_engine::resolve_anchor(&a,&changed).0,annotation_engine::AnchorStatus::Lost);let mut duplicate=blocks.clone();duplicate.push(Block{idx:2,kind:BlockKind::Paragraph,text:"Before selected quote after.".into()});a.heading=None;a.prefix.clear();a.suffix.clear();assert_eq!(annotation_engine::resolve_anchor(&a,&duplicate).0,annotation_engine::AnchorStatus::Ambiguous);assert!(annotation_engine::build_anchor(&[Block{idx:0,kind:BlockKind::Paragraph,text:"repeat repeat".into()}],0,"repeat").is_err());}
#[test]fn malformed_import_and_immutable_rewrites_roll_back(){let(a,b,id)=pair("editor");publish(&a,note(&id,"original")).unwrap();transfer(&a,&b,&id,"sync");let(p,doc,_,_)=b.margin_load(&id).unwrap();let mut records=Store::margin_records(&doc).unwrap().into_values().collect::<Vec<_>>();records[0].body="tampered historical content".into();let payload=serde_json::json!({"policy":p,"records":records,"acknowledged_hash":null});let me=b.margin_identity_private().unwrap();let packet=secure::seal(&me,&a.margin_contact().unwrap(),&id,p.data.epoch,"sync",&json(&payload).unwrap()).unwrap();assert!(a.margin_import_packet(&ImportRequest{packet,expected_owner:p.data.owner}).is_err());assert_eq!(a.margin_view(&id).unwrap().entries[0].versions[0].body,"original");assert!(a.margin_inspect("not JSON").is_err());}
